"02-08": { e: "🪁", name: "National Kite Flying Day", blurb: "Cold, clear, windy February is secretly the best kite weather of the year. Everyone forgets this.", also: ["National Molasses Bar Day", "Laugh and Get Rich Day", "Boy Scouts Day"] },
"02-09": { e: "\u{1F355}", name: "National Pizza Day", blurb: "The undisputed heavyweight. Argue about the toppings, the crust, and the correct city — that's part of the day.", also: ["National Bagels and Lox Day", "National Toothache Day", "Read in the Bathtub Day"] },
