"02-14": { e: "\u{1F49D}", name: "Valentine's Day", blurb: "Roses, chocolate, a card bought at 6pm at the pharmacy. Also National Ferris Wheel Day, which is arguably more fun.", also: ["National Ferris Wheel Day", "National Cream-Filled Chocolates Day", "National Organ Donor Day"] },
"02-15": { e: "\u{1F36C}", name: "National Gumdrop Day", blurb: "The candy nobody buys and everybody eats. Structural material for gingerbread houses, sugar-dusted and unbothered.", also: ["National Hippo Day", "Singles Awareness Day", "National Wisconsin Day"] },
